  },

  orderInvalid(result, siteUrl) {
    const options = (result && result.options) || [];
    switch (result && result.error) {
      case 'unknown_variant':
        return `I couldn't find that flavour. We have ${options.join(', ')}. Could you send the order again?`;
      case 'unknown_size':
